content.arguments:
{"description":"复核两文件哈希与红线","command":"$dir='./'
foreach($f in @('yelan.md','yelan.json')){
  $p=Join-Path $dir $f
  $all=[System.IO.File]::ReadAllText($p,[System.Text.Encoding]::UTF8)
  $idx=$all.LastIndexOf("EVIDENC./")
  $ev=$all.Substring($idx).TrimEnd("`r","`n")
  $body=$all.Substring(0,$idx)
  $body=$body -replace "`r`n","`n"
  $body=$body.TrimEnd("`n")
  $bytes=[System.Text.Encoding]::UTF8.GetBytes($body)
  $sha=[System.Security.Cryptography.SHA256]::Create().ComputeHash($bytes)
  $h=(-join ($sha | ForEach-Object { $_.ToString('x2') })).Substring(0,12)
  "== $f =="
  "  EVIDENCE行: $ev"
  "  实测 N=$($bytes.Length)  hash12=$h"
  $m=[regex]::Match($ev,'\|(\d+)\|([0-9a-f]{12})$')
  if($m.Success){ "  匹配: N=$(if($m.Groups[1].Value -eq "$($bytes.Length)"){'OK'}else{'MISMATCH'})  hash=$(if($m.Groups[2].Value -eq $h){'OK'}else{'MISMATCH'})" } else { "  解析失败" }
  "  半角波浪号: $([regex]::Matches($body,'(?<![~])~(?![~])').Count)  双波浪号: $([regex]::Matches($body,'~~').Count)  <br>: $([regex]::Matches($body,'<br').Count)"
  if($f -eq 'yelan.md'){
    "  小节标题: " + (([regex]::Matches($body,'(?m)^## .+$') | ForEach-Object { $_.Value }) -join ' ; ')
    $lines=$body -split "`n"
    $bad=@(); for($i=0;$i -lt $lines.Count;$i++){ $l=$lines[$i]; if($l -match '^\s*\|' -and $l.TrimEnd() -notmatch '\|$'){ $bad+="L$($i+1)" } }
    "  未以|收尾的表格行: " + $(if($bad.Count){$bad -join ','}else{'无'})
    "  行数: $($lines.Count)"
  } else {
    try { $o=$body | ConvertFrom-Json; "  JSON解析: OK  changes=$($o.changes.Count) unknowns=$($o.unknowns.Count) sources=$($o.sources.Count)" } catch { "  JSON解析失败: $($_.Exception.Message)" }
  }
}"}

