  $m=[regex]::Match($ev,'\|(\d+)\|([0-9a-f]{12})$')
  "== $f ==  实测 N=$($bytes.Length) hash12=$h  声明 N=$($m.Groups[1].Value) hash=$($m.Groups[2].Value)  $(if($m.Groups[1].Value -eq "$($bytes.Length)" -and $m.Groups[2].Value -eq $h){'一致 OK'}else{'不一致 FAIL'})"
  "   半角波浪号=$([regex]::Matches($body,'(?<![~])~(?![~])').Count)  <br>=$([regex]::Matches($body,'<br').Count)  wpotpack=$([regex]::Matches($body,'wpotpack').Count)  wotpack=$([regex]::Matches($body,'wotpack').Count)"
  if($f -eq 'yelan.md'){
    "   首行: " + (($body -split "`n")[0])
    "   第四种标签残留（结构已核/前半已核/高（结构））: " + ([regex]::Matches($body,'结构已核|前半已核|前两项结构已核').Count)
    "   三档方括号出现次数: [已核]=$([regex]::Matches($body,'\[已核\]').Count) [推断]=$([regex]::Matches($body,'\[推断\]').Count) [纯猜]=$([regex]::Matches($body,'\[纯猜\]').Count)"
  } else {
    try{$o=$body|ConvertFrom-Json; "   JSON OK: changes=$($o.changes.Count) unknowns=$($o.unknowns.Count) sources=$($o.sources.Count) sources_note=$(if($o.sources_note){'有'}else{'无'})"; "   gcsim链: " + (($o.sources|Where-Object{$_.url -match 'github'}).url)}catch{"   JSON FAIL: $($_.Exception.Message)"}
  }
}","description":"最终验收：哈希与修正项抽查"}

